def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the palette, a row or column of colors each repeated for
    # three cells in the perpendicular direction.
    palette = None
    for r in range(h - 2):
        cols = [c for c in range(w)
                if grid[r][c] != 0 and grid[r+1][c] == grid[r][c]
                and grid[r+2][c] == grid[r][c]]
        if len(cols) >= 2:
            palette = ("vertical", r, cols)
            break
    if palette is None:
        for c in range(w - 2):
            rows = [r for r in range(h)
                    if grid[r][c] != 0 and grid[r][c+1] == grid[r][c]
                    and grid[r][c+2] == grid[r][c]]
            if len(rows) >= 2:
                palette = ("horizontal", c, rows)
                break
    if palette is None:
        return grid

    orient, start, positions = palette
    if orient == "vertical":
        colors = [grid[start][c] for c in positions]
        keycells = {(r, c) for r in range(start, start+3) for c in positions}
    else:
        colors = [grid[r][start] for r in positions]
        keycells = {(r, c) for r in positions for c in range(start, start+3)}

    pts = [(r, c) for r in range(h) for c in range(w)
           if grid[r][c] != 0 and (r, c) not in keycells]
    if not pts:
        return grid

    minr, maxr = min(r for r, c in pts), max(r for r, c in pts)
    minc, maxc = min(c for r, c in pts), max(c for r, c in pts)
    shape = {(r-minr, c-minc) for r, c in pts}
    sh = maxr - minr + 1
    # The input silhouette is the copy matching the palette's center color.
    original = grid[minr][minc]
    idx = colors.index(original) if original in colors else len(colors)//2
    top = minr - idx * sh

    out = [[0] * w for _ in range(h)]
    for i, color in enumerate(colors):
        for dr, dc in shape:
            rr, cc = top + i*sh + dr, minc + dc
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = color
    return out
